<script setup lang="ts">
import {onBeforeUnmount,ref,watch} from 'vue'
import {useMemberStore} from '../stores/member'
import {memberApi,statusLabels,slotLabels,type Viewing,type ViewingStatus} from '../services/member'
import {catalogPhoto,catalogTitle} from '../services/catalog-photos'
import AppHeader from '../components/AppHeader.vue'
import AppIcon from '../components/AppIcon.vue'
import AppSheet from '../components/AppSheet.vue'
import MemberGate from '../components/MemberGate.vue'
import ViewingPlanner from '../components/ViewingPlanner.vue'
const member=useMemberStore(),status=ref<ViewingStatus>('PLANNED'),items=ref<Viewing[]>([]),page=ref(-1),total=ref(0),busy=ref(false),error=ref(''),selected=ref<Viewing>(),editing=ref(false),cancelOpen=ref(false),acting=ref(false)
let request=0
async function load(append=false){const id=++request;busy.value=true;error.value='';if(!append){items.value=[];page.value=-1;total.value=0}try{await member.restore();if(!member.loggedIn)return;const result=await member.privateCall(token=>memberApi.viewings(token,status.value,append?page.value+1:0));if(id!==request)return;items.value=append?[...items.value,...result.items]:result.items;page.value=result.page;total.value=result.total}catch(cause){if(id===request)error.value=cause instanceof Error?cause.message:'加载失败，请重试'}finally{if(id===request)busy.value=false}}
async function change(item:Viewing,next:ViewingStatus){const captured=member.token;if(acting.value||!captured)return;acting.value=true;error.value='';try{await member.privateCall(token=>memberApi.status(token,item.id,next));if(member.token!==captured)return;cancelOpen.value=false;await member.refresh();if(member.token===captured)await load()}catch(cause){if(member.token===captured)error.value=cause instanceof Error?cause.message:'修改失败，请重试'}finally{if(member.token===captured)acting.value=false}}
watch(()=>[member.token,status.value],()=>{cancelOpen.value=false;editing.value=false;selected.value=undefined;acting.value=false;void load()},{immediate:true})
onBeforeUnmount(()=>++request)
</script>
<template><AppHeader title="看房计划" hide-avatar/><main class="page viewings-page"><div class="rental-page-title"><h1>看房计划</h1><span v-if="member.loggedIn&&!busy" class="small muted">{{ total }} 条</span></div><p class="small muted viewing-disclaimer">个人安排，不代表房东或经纪人确认。</p><div class="pill-tabs" role="tablist" aria-label="计划状态"><button v-for="(label,key) in statusLabels" :key="key" role="tab" :aria-selected="status===key" @click="status=key">{{ label }}</button></div><MemberGate v-if="!member.loggedIn&&!member.loading" title="登录后管理看房计划"/><p v-else-if="busy&&!items.length" class="rental-loading" role="status">正在加载…</p><section v-else-if="error&&!items.length" class="rental-state" role="alert"><h2>计划暂时加载不了</h2><p>{{ error }}</p><button class="secondary" @click="load()">重试</button></section><section v-else-if="!items.length" class="rental-state"><AppIcon name="calendar" :size="32"/><h2>{{ status==='PLANNED'?'还没有待看的房子':status==='COMPLETED'?'还没有已看记录':'还没有取消的计划' }}</h2><p>先找一套喜欢的房子，再安排合适的时间。</p><RouterLink to="/listings" class="primary">去找房<AppIcon name="arrow-right"/></RouterLink></section><section v-else><article v-for="item in items" :key="item.id" data-testid="viewing-card" class="viewing-record"><RouterLink :to="`/listing/${item.listing.id}`" class="viewing-record-home"><img :src="catalogPhoto(item.listing)" alt="室内示意"/><span><strong>{{ catalogTitle(item.listing) }}</strong><small>{{ item.listing.district }} · {{ item.listing.area }}㎡</small></span><AppIcon name="chevron-right" :size="17"/></RouterLink><div class="viewing-time"><AppIcon name="calendar" :size="17"/><strong>{{ item.date }}</strong><span>{{ slotLabels[item.slot] }}</span></div><div v-if="status==='PLANNED'" class="viewing-record-actions"><button :disabled="acting" @click="selected=item;editing=true">修改时间</button><button :disabled="acting" @click="change(item,'COMPLETED')">标记已看</button><button :disabled="acting" @click="selected=item;cancelOpen=true">取消计划</button></div></article><p v-if="error" class="form-error" role="alert">{{ error }}</p><button v-if="items.length<total" class="secondary rental-load-more" :disabled="busy" @click="load(true)">{{ busy?'正在加载…':'加载更多' }}</button></section></main><ViewingPlanner v-if="selected" v-model="editing" :home="selected.listing" :existing="selected" @saved="load()"/><AppSheet v-model="cancelOpen" title="取消看房计划"><p>取消后会保留在“已取消”记录中，可以重新安排。</p><p v-if="error" class="form-error" role="alert">{{ error }}</p><template #footer><button class="primary" :disabled="acting" @click="selected&&change(selected,'CANCELLED')">{{ acting?'正在取消…':'确认取消' }}</button></template></AppSheet></template>
<style scoped>.viewing-disclaimer{margin:0 0 22px}.viewings-page>.pill-tabs{margin-bottom:24px}.viewing-record{border:1px solid var(--line);border-radius:18px;padding:18px;margin-bottom:16px}.viewing-record-home{display:flex;align-items:center;gap:13px}.viewing-record-home img{width:68px;height:76px;border-radius:11px;object-fit:cover;flex-shrink:0}.viewing-record-home>span{flex:1;min-width:0}.viewing-record-home strong{display:block;font-size:14px;line-height:1.7}.viewing-record-home small{display:block;font-size:12px;color:var(--muted);margin-top:7px}.viewing-time{display:flex;align-items:center;gap:10px;margin-top:20px;padding:14px 0;border-top:1px solid var(--line);font-size:13px;flex-wrap:wrap}.viewing-time strong{font-weight:500}.viewing-time span{color:var(--muted);margin-left:auto}.viewing-record-actions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.viewing-record-actions button{min-height:44px;border-radius:10px;background:var(--surface);font-size:12px;padding:8px 2px}@media(max-width:359px){.viewing-record{padding:14px}.viewing-record-actions{gap:6px}}</style>
